import json,wave,array,math,csv,hashlib,pathlib
root=pathlib.Path.cwd();speech=json.loads((root/'src/content/speech.json').read_text());manifest=json.loads((root/'art/manifest.json').read_text());assets={a['assetId']:a for a in manifest['assets']};out=root/'docs/evidence/demo-repair-2026-10-12';rows=[]
core={'request-apple','request-banana','word-burger','word-cheese-burger','word-vanilla-cup','word-vanilla-cone','name-one','name-two','vocab-name-kettle','vocab-name-watering-can','menu-story','prologue-0'}
for id,s in speech.items():
 a=assets['audio-'+id];p=root/a['path'];b=p.read_bytes()
 with wave.open(str(p),'rb') as w:
  ch=w.getnchannels();rate=w.getframerate();sw=w.getsampwidth();n=w.getnframes();v=array.array('h',w.readframes(n));peak=max(map(abs,v),default=0);rms=math.sqrt(sum(x*x for x in v)/len(v)) if v else 0;clipped=sum(abs(x)>=32760 for x in v);silence=sum(abs(x)<327 for x in v)
 rows.append({'priority':'CORE' if id in core or id.startswith('world-') or id.startswith('request-') else 'ALL_REACHABLE_CATALOG','id':id,'text':s['text'],'path':a['path'],'duration_s':round(n/rate,4),'channels':ch,'sample_rate':rate,'bits':sw*8,'peak_dbfs':round(20*math.log10(max(1,peak)/32768),2),'rms_dbfs':round(20*math.log10(max(1,rms)/32768),2),'clipped_samples':clipped,'low_signal_fraction':round(silence/max(1,len(v)),4),'sha256':hashlib.sha256(b).hexdigest(),'text_pronunciation_segmentation_volume_image_age_review':'NOT_RUN_NO_HUMAN_REVIEWER','rights':'PENDING','development_status':s['status']})
with (out/'audio-review-queue.csv').open('w') as f:
 cw=csv.DictWriter(f,fieldnames=rows[0].keys());cw.writeheader();cw.writerows(rows)
summary={'scope':'All speech.json entries conservatively queued, including every reachable catalog, not only core. Orphan/historical audio listed separately. Technical PCM readings are not pronunciation, listening, volume comfort, or child acceptance.','speech_count':len(rows),'core_priority_count':sum(r['priority']=='CORE' for r in rows),'technical_zero_signal':[r['id'] for r in rows if r['peak_dbfs']<=-90],'any_saturated_samples':[r['id'] for r in rows if r['clipped_samples']>0],'formats':sorted(set((r['sample_rate'],r['bits'],r['channels']) for r in rows)),'range_duration_s':[min(r['duration_s'] for r in rows),max(r['duration_s'] for r in rows)],'registered_audio_count':sum(a['format']=='wav' for a in manifest['assets']),'unreferenced_registered_audio':[a['path'] for a in manifest['assets'] if a['format']=='wav' and a['assetId'][6:] not in speech],'acceptance':{'human_listening':'BLOCKED_USER_NO_REVIEWER','distribution_rights':'PENDING','teaching_age':'PENDING','child_observation':'NOT_RUN_NO_OBSERVER_OR_GUARDIAN_CONSENT'}}
